/bin/bash -lc "python - <<'PY'
import json, os, requests
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f:
    key=f.read().strip()
history_id='bbd44e69cb8906b54825319f91918aef'
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/kraken2/kraken2/2.17.1+galaxy0'
r2='f9cad7b01a472135091c5659b4d09e74'
inputs={
  'single_paired': {
    'single_paired_selector': 'no',
    'input_sequences': {'src':'hda','id':r2}
  },
  'split_reads': False,
  'report': {
    'create_report': 'true',
    'use_mpa_style': False,
    'report_zero_counts': False,
    'report_minimizer_data': False
  },
  'kraken2_database': '2025-02-05T204609Z_standard_prebuilt_core_nt_2024-09-04'
}
payload={'history_id':history_id,'tool_id':tool_id,'inputs':inputs,'input_format':'21.01'}
r=requests.post(f'{url}/api/tools', params={'key':key}, json=payload, timeout=60)
print('status', r.status_code)
try:
    data=r.json()
except Exception:
    print(r.text[:1000]); raise
print(json.dumps({k:data.get(k) for k in ['jobs','outputs','output_collections','implicit_collections','errors']}, indent=2))
PY"

