/bin/bash -lc "python - <<'PY'
import os, requests, json, re
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
tool='toolshed.g2.bx.psu.edu/repos/iuc/rna_starsolo/rna_starsolo/2.7.11b+galaxy2'
r=requests.get(f'{url}/api/tools/{tool}', params={'key':key,'io_details':'true'}, timeout=60)
print('status', r.status_code)
d=r.json()
# recursively find dicts with name genomeDir options
def walk(x, path=''):
    if isinstance(x, dict):
        if x.get('name')=='genomeDir' and 'options' in x:
            opts=x['options']
            print('genomeDir at', path, 'options', len(opts))
            for opt in opts:
                label=str(opt[0] if isinstance(opt,(list,tuple)) else opt.get('label',''))
                val=str(opt[1] if isinstance(opt,(list,tuple)) and len(opt)>1 else opt.get('value',''))
                if re.search(r'(Homo|human|GRCh38|hg38|Mus |mouse|GRCm39|mm10|mm39|Sus|pig|Sscrofa)', label+val, re.I):
                    print(label[:160], '=>', val)
        for k,v in x.items(): walk(v, path+'/'+str(k))
    elif isinstance(x, list):
        for i,v in enumerate(x): walk(v, path+f'[{i}]')
walk(d)
PY"

